package com.game_manager.gm.workflow; import com.game_manager.gm.common.security.*; import com.game_manager.gm.document.DocumentAccessExtension; import java.util.UUID; import org.springframework.stereotype.Component;
@Component public class WorkflowDocumentAccess implements DocumentAccessExtension {private final WorkflowInstanceRepository instances;private final WorkflowStepRepository steps;public WorkflowDocumentAccess(WorkflowInstanceRepository i,WorkflowStepRepository s){instances=i;steps=s;}public String resourceType(){return "WORKFLOW_ATTACHMENT";}public boolean allowed(UUID id,AuthenticatedUser actor){return instances.detail(id).map(i->{if(i.getRequesterId().equals(actor.id())||RolePermissions.has(actor.role(),Permission.WORKFLOW_MANAGE))return true;return steps.findByInstanceIdAndStatus(id,StepStatus.ACTIVE).map(s->s.getAssigneeId()!=null?s.getAssigneeId().equals(actor.id()):s.getAssigneeRole().equals(actor.role().name())).orElse(false);}).orElse(false);}}
